import AddAdminDialog from "@/components/TicketManagement/AllDialogs/AddAdminDialog.vue";
import DeleteAdmin from "@/components/TicketManagement/AllDialogs/DeleteAdmin.vue";
import SnackBar from "@/components/SnackBar.vue";
import { list_products_admins } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  components: {
    AddAdminDialog,
    DeleteAdmin,
    SnackBar
  },
  data() {
    return {
      height: 0,
      fixed: true,
      tableData: [],
      adminsinfo: {},
      tableLoading: false,
      addDialog: false,
      search: "",
      headers: [{
        text: "Admins",
        value: "user_email_id",
        sortable: false
      }, {
        text: "Action",
        value: "action",
        sortable: false
      }],
      componentCheck: 0,
      deleteDialog: false,
      rowInfo: {},
      SnackBarComponent: {}
    };
  },
  created() {
    this.height = window.innerHeight - 230;
    this.get_all_admins();
  },
  methods: {
    delete_admins(item) {
      this.componentCheck = 2;
      this.rowInfo = item;
      this.deleteDialog = true;
    },
    add_admins() {
      this.addDialog = true;
      this.componentCheck = 1;
    },
    async get_all_admins() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_products_admins, {
          product_id: this.$store.getters.Getproductitems.product_id
        }));
        this.tableLoading = false;
        var response = JSON.parse(result.data.list_products_admins);
        if (response.Status == "SUCCESS") {
          this.tableLoading = false;
          this.tableData = response.data;
        } else {
          this.tableLoading = false;
        }
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.addDialog = false;
      this.deleteDialog = false;
      this.get_all_admins();
    }
    // get_all_admins(){
    //  list_products_admins
    // },
  }
};
